answers.workaround:
The current workaround is to rewrite the function in the target runtime language. For example:
```C#
float screenScale = 1;
// Use Godot's dpi screen scale handling in EditorSettings::get_auto_display_scale() for ref (https://github.com/godotengine/godot/blob/5675c76461e197d3929a1142cfb84ab1a76ac9dd/editor/editor_settings.cpp#L1575)
if (OS.GetName() == "Linux" && DisplayServer.GetName() == "Wayland")
{
    float mainWindowScale = DisplayServer.ScreenGetScale();
    if (DisplayServer.GetScreenCount() == 1 || mainWindowScale % 1 != 0)
    {
        screenScale = mainWindowScale;
    }
    else
    {
        screenScale = DisplayServer.ScreenGetMaxScale();
    }
}
else if (OS.GetName() == "macOS" || OS.GetName() == "Android")
{
    screenScale = DisplayServer.ScreenGetMaxScale();
}
else
{
    int screen = DisplayServer.WindowGetCurrentScreen();
    if (DisplayServer.ScreenGetSize(screen) == Vector2.Zero)
    {
        screenScale = 1;
    }
    else
    {
        int smallestDimension = Mathf.Min(DisplayServer.ScreenGetSize(screen).X, DisplayServer.ScreenGetSize(screen).Y);
        if (DisplayServer.ScreenGetDpi(screen) >= 192 && smallestDimension >= 1400)
        {
            screenScale = 2;
        }
        else if (smallestDimension >= 1700)
        {
            screenScale = 1.5f;
        }
        else if (smallestDimension <= 800)
        {
            screenScale = 0.75f;
        }
    }
}

GD.Print($"Screen DPI: {DisplayServer.ScreenGetDpi()}, using target scale: {screenScale}");

// Scale your UI accordingly, using the screenScale factor.
// ...
```
